'use strict';
const $=id=>document.getElementById(id),all=q=>[...document.querySelectorAll(q)];
const state={mode:'demo',preset:'structure',strength:1,steps:40,records:[],current:null,frames:[],frame:0,input:'examples/original.png',filename:'astronaut.png',source:'NASA / Eileen Collins · Public domain, via scikit-image',width:256,height:256,busy:false,cancel:false,timer:null,base:null,models:{},db:null};
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function stop(){clearInterval(state.timer);state.timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','播放迭代过程');}
function displayFrame(index){if(!state.frames.length)return;state.frame=Math.max(0,Math.min(index,state.frames.length-1));const f=state.frames[state.frame];$('resultImage').src=f.url;$('timeline').value=state.frame;const total=state.frames.at(-1).step;$('frameLabel').textContent=`${f.step} / ${total}`;$('stepTag').textContent=`ITERATION ${String(f.step).padStart(3,'0')}`;$('resultState').textContent=`${f.step} 次像素更新`;}
function mode(m){if(state.busy)return;state.mode=m;$('demoMode').classList.toggle('selected',m==='demo');$('createMode').classList.toggle('selected',m==='create');$('runtimeLabel').textContent=m==='demo'?'预计算案例 · 可离线回放':'本地计算 · 图像不上传服务器';}
function syncControls(){all('[data-preset]').forEach(b=>{const on=b.dataset.preset===state.preset;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});all('[data-steps]').forEach(b=>{const on=+b.dataset.steps===state.steps;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});$('strength').value=state.strength;$('strengthLabel').textContent=['低','中','高'][state.strength];}
function selectRecord(record){if(state.busy)return;stop();state.current=record;state.input=record.original;state.filename=record.filename;state.source=record.source;state.width=record.width;state.height=record.height;state.originalWidth=record.originalWidth||record.width;state.originalHeight=record.originalHeight||record.height;state.frames=record.frames;state.preset=record.preset;state.steps=record.iterations;state.strength=['低','中','高'].indexOf(record.strength);if(state.strength<0)state.strength=1;$('inputImage').src=record.original;$('inputImage').alt=`原图：${record.filename}`;$('inputName').textContent=record.filename;$('dimensions').textContent=`${record.width} × ${record.height}`;$('sourceLine').textContent=record.source+ (record.builtin?' · 技术示例，待替换为小组作品':'');$('resultLayer').textContent=record.layer;$('resultBadge').textContent='真实运行结果';$('timeline').max=record.frames.length-1;displayFrame(record.frames.length-1);syncControls();status('已载入真实运行记录。改变参数后可重新生成。');renderRecords();enableExports(true);}
function enableExports(on){for(const id of ['download','settings'])$(id).disabled=!on;}
function renderRecords(){const container=$('records');container.replaceChildren();for(const r of state.records){const b=document.createElement('button');b.className='record-card'+(state.current?.id===r.id?' selected':'');const img=document.createElement('img');img.className='record-image';img.src=r.frames.at(-1).url;img.alt=r.title;img.loading='lazy';const info=document.createElement('div');info.className='record-info';const row=document.createElement('div');row.className='record-topline';const title=document.createElement('h3');title.textContent=r.title;const arrow=document.createElement('span');arrow.textContent='↗';row.append(title,arrow);const detail=document.createElement('p');detail.textContent=`${r.layer} · ${r.iterations} STEPS · ${r.builtin?'DEMO':'YOUR CREATION'}`;info.append(row,detail);b.append(img,info);b.onclick=()=>{mode(r.builtin?'demo':'create');selectRecord(r);$('lab').scrollIntoView({behavior:'smooth'});};b.disabled=state.busy;container.append(b);}const add=document.createElement('button');add.className='new-record';add.innerHTML='<b>＋</b><span>下一场梦，由你开始</span><small>上传照片 · 探索另一种可能</small>';add.disabled=state.busy;add.onclick=()=>{mode('create');$('fileInput').click();};container.append(add);$('archiveCount').textContent=String(state.records.length).padStart(2,'0');}
async function initDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('neural-dreams-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('records',{keyPath:'id'});request.onerror=()=>reject(request.error);request.onsuccess=()=>resolve(request.result);});}
async function savedRecords(){if(!state.db)return[];return new Promise((resolve,reject)=>{const r=state.db.transaction('records').objectStore('records').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function persist(r){if(r.builtin)return;if(!state.db){toast('浏览器存储不可用，请下载完整作品包备份。');return;}return new Promise(resolve=>{const tx=state.db.transaction('records','readwrite');tx.objectStore('records').put(r);tx.oncomplete=resolve;tx.onerror=()=>{toast('本地保存失败，请下载完整作品包备份。');resolve();};});}
function imageLoad(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('无法读取图片，请选择有效的 JPG 或 PNG。'));image.src=src;});}
async function upload(file){if(!file||state.busy)return;if(!['image/jpeg','image/png'].includes(file.type)){toast('请选择 JPG 或 PNG 图片。');return;}if(file.size>20*1024*1024){toast('图片超过 20 MB，请先缩小后上传。');return;}const url=URL.createObjectURL(file);try{const img=await imageLoad(url);if(img.width<32||img.height<32)throw new Error('图片太小，请使用至少 32 × 32 像素的图片。');if(img.width*img.height>50e6)throw new Error('图片超过 5000 万像素，请先缩小后再试。');if(Math.max(img.width/img.height,img.height/img.width)>8)throw new Error('图片比例过于狭长，请使用宽高比不超过 8:1 的图片。');const scale=Math.min(1,256/Math.max(img.width,img.height)),w=Math.round(img.width*scale),h=Math.round(img.height*scale);const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);const data=canvas.toDataURL('image/png');stop();mode('create');state.current=null;state.input=data;state.filename=file.name;state.source='用户上传 · 拍摄者 / 许可来源待填写';state.width=w;state.height=h;state.originalWidth=img.width;state.originalHeight=img.height;state.frames=[{step:0,url:data}];$('inputImage').src=data;$('inputImage').alt='已上传的原始图像';$('inputName').textContent=file.name;$('dimensions').textContent=`${w} × ${h}`;$('resultImage').alt='等待生成的图像';$('resultBadge').textContent='待生成';$('resultLayer').textContent='尚未运行';$('sourceLine').textContent=`原始 ${img.width} × ${img.height} → 输出 ${w} × ${h} · 按比例缩小，不裁剪`;$('timeline').max=0;displayFrame(0);enableExports(false);renderRecords();status('图片已准备好。选择参数，开始真实 DeepDream 生成。');$('lab').scrollIntoView({behavior:'smooth'});}catch(e){toast(e.message);}finally{URL.revokeObjectURL(url);$('fileInput').value='';}}
async function ensureModel(){if(state.base)return;status('正在加载本地预训练模型…首次运行需要片刻。');if(!window.tf)throw new Error('计算库加载失败，请刷新页面重试。');try{await tf.setBackend('webgl');}catch{await tf.setBackend('cpu');}await tf.ready();const base=await tf.loadLayersModel('model/model.json');base.trainable=false;state.base=base;}
function setBusy(on){state.busy=on;all('[data-preset],[data-steps],#strength,#generate,#demoMode,#createMode,#imageUpload,#uploadBottom,#fileInput,#settings,#download,.record-card,.new-record').forEach(b=>b.disabled=on);$('cancel').hidden=!on;$('progress').hidden=!on;if(!on)enableExports(!!state.current);$('generate').querySelector('span').textContent=on?'正在增强特征…':'用这些参数生成';}
async function tensorPNG(t){const pixels=tf.tidy(()=>t.squeeze().add(1).mul(127.5).clipByValue(0,255).cast('int32'));try{const canvas=document.createElement('canvas');await tf.browser.toPixels(pixels,canvas);return canvas.toDataURL('image/png');}finally{pixels.dispose();}}
async function generate(){if(state.busy)return;stop();mode('create');setBusy(true);state.cancel=false;$('progressBar').style.width='0%';const prior=state.current;let x;try{await ensureModel();if(state.cancel)throw new Error('已停止生成，输入图和设置已保留。');const key=state.preset,steps=state.steps,rate=[.006,.012,.02][state.strength],strength=['低','中','高'][state.strength];const model=state.models[key]||(state.models[key]=DreamEngine.extractor(tf,state.base,key));const img=await imageLoad(state.input);x=tf.tidy(()=>tf.browser.fromPixels(img).toFloat().div(127.5).sub(1).expandDims());const frames=[{step:0,url:state.input}],started=performance.now();state.frames=frames;$('timeline').max=0;$('resultBadge').textContent='真实计算中';$('resultLayer').textContent=DreamEngine.presets[key].layer;displayFrame(0);
for(let i=1;i<=steps;i++){if(state.cancel)throw new Error('已停止生成，输入图和设置已保留。');const next=DreamEngine.step(tf,model,x,rate);x.dispose();x=next;if(i%2===0||i===steps){frames.push({step:i,url:await tensorPNG(x)});$('timeline').max=frames.length-1;displayFrame(frames.length-1);}$('progressBar').style.width=`${i/steps*100}%`;status(`真实像素优化 ${i} / ${steps} · ${Math.round((performance.now()-started)/1000)} 秒 · 模型固定`);await tf.nextFrame();}
const record={id:'run-'+Date.now(),title:`未命名梦境 · ${DreamEngine.presets[key].name}`,preset:key,layer:DreamEngine.presets[key].layer,model:'MobileNet V1 · 0.25 · ImageNet',strength,stepSize:rate,iterations:steps,width:state.width,height:state.height,originalWidth:state.originalWidth||state.width,originalHeight:state.originalHeight||state.height,createdAt:new Date().toISOString(),source:state.source,filename:state.filename,original:state.input,frames,elapsedMs:Math.round(performance.now()-started),engine:'TensorFlow.js 4.22.0 / '+tf.getBackend(),objective:'mean activation; gradient normalized by RMS; input clipped to [-1,1]',crop:false};state.records.push(record);await persist(record);setBusy(false);selectRecord(record);$('resultImage').alt='真实 DeepDream 生成结果';status(`生成完成 · ${steps} 次迭代 · ${(record.elapsedMs/1000).toFixed(1)} 秒。记录已加入创作档案。`);toast('梦境已生成，可下载图像或导出完整作品包。');
}catch(e){state.current=prior;if(prior){state.frames=prior.frames;$('timeline').max=prior.frames.length-1;displayFrame(prior.frames.length-1);$('resultLayer').textContent=prior.layer;$('resultBadge').textContent='上次完成结果';}else{state.frames=[{step:0,url:state.input}];$('timeline').max=0;displayFrame(0);$('resultBadge').textContent='未完成';}$('runtimeLabel').textContent='输入和设置已保留 · 可重试';status(e.message||'生成失败，请重试或切换演示案例。',true);toast('可重试生成，或点击“演示案例”回到已保存的真实结果。');}finally{x?.dispose();setBusy(false);}}
function download(blob,filename){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function safeName(value){return value.replace(/[\\/:*?"<>|]/g,'_').slice(0,80)||'DeepDream';}
function metadata(r){const {frames,original,...meta}=r;return {...meta,original:'original.png',final:'final.png',frames:frames.map(f=>({step:f.step,file:`frames/step-${String(f.step).padStart(3,'0')}.png`})),method:'Fixed pretrained network; gradient ascent on input pixels only. Dream is a metaphor, not a claim of subjective experience.'};}
function recordNotes(){const r=state.current;if(!r)return;r.title=$('artTitle').value.trim()||'未命名梦境';r.source=$('artSource').value.trim()||'来源待填写';r.note=$('artNote').value.trim();r.scientistNote=$('scientistNote').value.trim();r.artistNote=$('artistNote').value.trim();renderRecords();$('sourceLine').textContent=r.source;persist(r);}
function openSettings(){if(!state.current)return;const r=state.current;$('artTitle').value=r.title;$('artSource').value=r.source;$('artNote').value=r.note||'';$('scientistNote').value=r.scientistNote||'';$('artistNote').value=r.artistNote||'';$('recordDetails').textContent=`MODEL       ${r.model}\nLAYER       ${r.layer}\nSTEP SIZE   ${r.stepSize} / ${r.strength}\nITERATIONS  ${r.iterations} / ${r.frames.length} 个真实帧\nOUTPUT      ${r.width} × ${r.height} / 不裁剪\nENGINE      ${r.engine}\nCREATED     ${new Date(r.createdAt).toLocaleString('zh-CN')}\nDURATION    ${(r.elapsedMs/1000).toFixed(1)} 秒`;$('recordDialog').showModal();}
async function exportPack(){if(!state.current)return;recordNotes();const r=state.current,b=$('exportPack');b.disabled=true;try{const urls=[{name:'original.png',url:r.original},{name:'final.png',url:r.frames.at(-1).url},...r.frames.map(f=>({name:`frames/step-${String(f.step).padStart(3,'0')}.png`,url:f.url}))];const files=await Promise.all(urls.map(async f=>{const res=await fetch(f.url);if(!res.ok)throw new Error('图像读取失败');return{name:f.name,data:new Uint8Array(await res.arrayBuffer())};}));files.push({name:'record.json',data:JSON.stringify(metadata(r),null,2)},{name:'README.txt',data:`Neural Network Dreams\n${r.title}\n${r.source}\n\nFixed pretrained model; gradient ascent on pixels only.\nAll frames are real computed snapshots; no interpolation.\nSee record.json for method and parameters.\n\n观察: ${r.note||'待填写'}\nScientist: ${r.scientistNote||'待填写'}\nArtist: ${r.artistNote||'待填写'}\n\nReferences:\nhttps://www.tensorflow.org/tutorials/generative/deepdream\nhttps://research.google/blog/inceptionism-going-deeper-into-neural-networks/\nhttps://memo.tv/projects/2017/learning-to-see-interactive/\n`});download(makeZip(files),safeName(r.title)+'.zip');toast('作品包已导出：原图、过程帧、最终图、参数与备注。');}catch(e){toast('导出失败：'+e.message);}finally{b.disabled=false;}}
$('play').onclick=()=>{if(state.timer){stop();return;}if(state.frames.length<2){toast('请先生成图像或选择演示案例。');return;}if(state.frame===state.frames.length-1)displayFrame(0);$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停迭代过程');state.timer=setInterval(()=>{if(state.frame>=state.frames.length-1){stop();return;}displayFrame(state.frame+1);},500);};
$('timeline').oninput=e=>{stop();displayFrame(+e.target.value);};$('replay').onclick=()=>{stop();displayFrame(0);};
all('[data-preset]').forEach(b=>b.onclick=()=>{state.preset=b.dataset.preset;syncControls();if(state.mode==='demo'){const record=state.records.find(r=>r.builtin&&r.preset===state.preset);if(record)selectRecord(record);}else status('已调整待生成参数；当前显示的图像仍属于上次运行。');});
all('[data-steps]').forEach(b=>b.onclick=()=>{state.steps=+b.dataset.steps;syncControls();status('已调整待生成参数；点击生成以应用。');});
$('strength').oninput=e=>{state.strength=+e.target.value;syncControls();status('已调整待生成强度；点击生成以应用。');};
$('demoMode').onclick=()=>{mode('demo');const r=state.records.find(r=>r.builtin&&r.preset===state.preset);if(r)selectRecord(r);};$('createMode').onclick=()=>{mode('create');status('可上传自己的照片，也可用当前图片探索新参数。');};
for(const id of ['imageUpload','uploadBottom'])$(id).onclick=()=>{mode('create');$('fileInput').click();};$('fileInput').onchange=e=>upload(e.target.files[0]);
$('generate').onclick=generate;$('cancel').onclick=()=>{state.cancel=true;status('正在停止，保留输入和设置…');};
$('settings').onclick=openSettings;$('saveNotes').onclick=()=>{recordNotes();toast(state.current.builtin?'示例备注已更新；请导出作品包保存。':'备注已保存至当前浏览器。');};$('exportJson').onclick=()=>{recordNotes();download(new Blob([JSON.stringify(metadata(state.current),null,2)],{type:'application/json'}),safeName(state.current.title)+'.json');};$('exportPack').onclick=exportPack;
$('download').onclick=async()=>{try{const r=state.current;if(!r)return;const res=await fetch(r.frames.at(-1).url);if(!res.ok)throw new Error();download(await res.blob(),safeName(r.title)+'.png');}catch{toast('下载失败，请重试。');}};
for(const id of ['methodTop','methodFooter'])$(id).onclick=()=>$('methodDialog').showModal();all('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());all('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
$('present').onclick=()=>{const on=document.body.classList.toggle('presenting');$('present').querySelector('span').textContent=on?'退出课堂模式':'课堂模式';window.scrollTo({top:0,behavior:'smooth'});};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('presenting')){document.body.classList.remove('presenting');$('present').querySelector('span').textContent='课堂模式';}});
(async()=>{try{const response=await fetch('examples/manifest.json');if(!response.ok)throw new Error('案例读取失败');const examples=await response.json();state.records=examples.map(r=>({...r,builtin:true}));try{state.db=await initDB();state.records.push(...await savedRecords());}catch{toast('浏览器存储不可用；生成后请下载作品包备份。');}selectRecord(state.records.find(r=>r.preset==='structure')||state.records[0]);}catch(e){enableExports(false);status('演示案例未能加载，请刷新；仍可上传图片尝试生成。',true);mode('create');renderRecords();}})();
